```js
import express from "express";
import { randomUUID } from "node:crypto";
import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { StreamableHTTPServerTransport } from "@modelcontextprotocol/sdk/server/streamableHttp.js";
import { isInitializeRequest } from "@modelcontextprotocol/sdk/types.js";

const app = express();
app.use(express.json());
const transports = {};

async function handle(req, res) {
  const sessionId = req.headers["mcp-session-id"];
  console.log(`[srv] ${req.method} method=${req.body?.method ?? "-"} mcp-session-id=${sessionId ?? "<MISSING>"}`);
  let transport;
  if (sessionId && transports[sessionId]) {
    transport = transports[sessionId];
  } else if (!sessionId && req.method === "POST" && isInitializeRequest(req.body)) {
    transport = new StreamableHTTPServerTransport({
      sessionIdGenerator: () => randomUUID(),
      onsessioninitialized: (sid) => { transports[sid] = transport; },
    });
    const server = new McpServer({ name: "harness", version: "1.0.0" });
    server.registerTool("get_capabilities", { description: "returns caps", inputSchema: {} }, async () => ({
      content: [{ type: "text", text: "caps-ok " + new Date().toISOString() }],
    }));
    await server.connect(transport);
  } else {
    return res.status(400).json({ jsonrpc: "2.0", error: { code: -32000, message: "Bad Request: No valid session ID provided." }, id: null });
  }
  await transport.handleRequest(req, res, req.body);
}

